package waiting

import (
	"os"
	"slices"
	"sort"
	"testing"

	"github.com/Jlore-Studios/JackiOh/bot/go/internal/pyjson"
	"github.com/Jlore-Studios/JackiOh/bot/go/internal/queue"
)

// python.json is what bot/harness/waiting.py answers for each input (generated by running it).
func expected(t *testing.T) *pyjson.Object {
	t.Helper()
	raw, err := os.ReadFile("testdata/python.json")
	if err != nil {
		t.Fatal(err)
	}
	data, err := pyjson.Loads(raw)
	if err != nil {
		t.Fatal(err)
	}
	return data.(*pyjson.Object)
}

// Reviews and revisions: a build's need asks providers.tier_at_least, which is not ported here.
func TestNeedMatchesPython(t *testing.T) {
	for _, row := range expected(t).List("need") {
		r := row.([]any)
		extra := r[2].(*pyjson.Object)
		c := queue.NewCandidate(7, r[0].(string), "t", false, "")
		c.Difficulty = r[1].(string)
		c.ReviewFloor, c.AuditTier = extra.Str("review_floor"), extra.Str("audit_tier")
		c.BotPR, c.Conflict = extra.Bool("bot_pr"), extra.Bool("conflict")
		step, tier, why := Need(c)
		if got, want := pyjson.Dumps([]any{step, tier, why}), pyjson.Dumps(r[3]); got != want {
			t.Errorf("Need(%s %s %s) = %s, want %s", r[0], r[1], pyjson.Dumps(extra), got, want)
		}
	}
}

func TestHeldRows(t *testing.T) {
	rows := HeldRows(map[int]string{9: "labelled `human`", 2: "waits for #1 to close"},
		[]*pyjson.Object{pyjson.New("number", 2, "title", "Patch (part 2 of 2)"), pyjson.New("number", 3, "title", nil)})
	if len(rows) != 2 || rows[0].Number != 2 || rows[0].Title != "Patch (part 2 of 2)" ||
		rows[0].Waiting != "waits for #1 to close" || !rows[0].Held || rows[0].Step != "build" ||
		rows[0].Priority != "none" || rows[1].Number != 9 || rows[1].Title != "" {
		t.Errorf("HeldRows = %+v %+v", rows[0], rows[1])
	}
}

func TestPlannersOrder(t *testing.T) {
	c := func(number int, kind, difficulty string, forced bool, priority int) *queue.Candidate {
		x := queue.NewCandidate(number, kind, "", forced, "2026-01-01")
		x.Difficulty, x.Priority = difficulty, priority
		return x
	}
	order := []*queue.Candidate{
		c(1, "build", "easy", false, 2), c(2, "build", "hard", false, 2), c(3, "revise", "medium", false, 0),
		c(4, "review", "medium", false, 3), c(5, "build", "medium", true, 3), c(6, "build", "easy", false, 1),
	}
	starts := pyjson.New("6", nil)
	sort.SliceStable(order, func(i, j int) bool { return lessByPlanner(order[i], order[j], starts) })
	var got []int
	for _, x := range order {
		got = append(got, x.Number)
	}
	if want := []int{6, 5, 4, 3, 2, 1}; !slices.Equal(got, want) {
		t.Errorf("order %v, want %v", got, want)
	}
}
